function track(PDO $pdo,$caseId,$type){$s=$pdo->prepare('SELECT * FROM uat_tracks WHERE case_id=? AND track_type=? AND set_no=1');$s->execute([$caseId,$type]);return $s->fetch()?:null;}
function trackExtras(PDO $pdo,$trackId,$table){if(!$trackId)return[];$s=$pdo->prepare("SELECT * FROM $table WHERE track_id=? ORDER BY id");$s->execute([$trackId]);return$s->fetchAll();}
