<script>let si=<?=count($subjects)?>;function addSubject(){document.getElementById('subjects').insertAdjacentHTML('beforeend',`<div class="subject"><div class="grid"><div><label>คำนำหน้า</label><input name="subjects[${si}][title]"></div><div><label>ชื่อ</label><input name="subjects[${si}][first]" required></div><div><label>นามสกุล</label><input name="subjects[${si}][last]"></div><div><label>ตำแหน่ง</label><input name="subjects[${si}][position]"></div><div><label>ประเภทบุคลากร</label><select name="subjects[${si}][employment]"><option value="">-- เลือก --</option><option>ข้าราชการกรุงเทพมหานครสามัญ</option><option>ข้าราชการครูและบุคลากรทางการศึกษากรุงเทพมหานคร</option><option>ข้าราชการในสถาบันอุดมศึกษา</option><option>พนักงานราชการกรุงเทพมหานคร</option><option>ลูกจ้าง</option></select></div><div><label>สถานะปัจจุบัน</label><select name="subjects[${si}][status]"><option>ปฏิบัติงานอยู่</option><option>พ้นจากราชการ/พ้นจากงาน</option><option>เกษียณอายุ</option><option>ลาออก</option></select></div></div></div>`);si++;}</script>
<script>
(() => {
  const existingNationalIds = <?=json_encode(canViewSubjectIdentity()?array_column($subjects,'national_id'):[])?>;
  function addNationalIdField(card, index) {
    if (card.querySelector('[name$="[national_id]"]')) return;
    const grid = card.querySelector('.grid'); if (!grid) return;
    const field = document.createElement('div');
    const current = existingNationalIds[index] || '';
    field.innerHTML = '<label>เลขบัตรประชาชนผู้ถูกกล่าวหา</label><input inputmode="numeric" maxlength="13" pattern="[0-9]{13}" name="subjects['+index+'][national_id]" value="'+current.replace(/&/g,'&amp;').replace(/"/g,'&quot;')+'" placeholder="13 หลัก">';
    grid.appendChild(field);
  }
  const root = document.getElementById('subjects');
  if (!root) return;
  root.querySelectorAll('.subject').forEach((card,index) => addNationalIdField(card,index));
  new MutationObserver(() => root.querySelectorAll('.subject').forEach((card,index) => addNationalIdField(card,index))).observe(root,{childList:true,subtree:true});
})();
</script>
